    public interface ITokenService
    {
        string GenerateSessionToken(string userId);
        bool ValidateToken(string token);
    }

    public interface IEncryptionService
    {
        byte[] Encrypt(byte[] plaintext, byte[] key);
        byte[] Decrypt(byte[] ciphertext, byte[] key);
    }

    public class AesEncryptionService : IEncryptionService
    {
        // AES-GCM provides authenticated encryption (confidentiality + integrity).
        private const int NonceSize = 12; // 96-bit nonce recommended for GCM
        private const int TagSize = 16;    // 128-bit authentication tag

        public byte[] Encrypt(byte[] plaintext, byte[] key)
        {
            if (plaintext == null) throw new ArgumentNullException(nameof(plaintext));
            if (key == null) throw new ArgumentNullException(nameof(key));

            var nonce = new byte[NonceSize];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(nonce);
            }

            var ciphertext = new byte[plaintext.Length];
            var tag = new byte[TagSize];

            using (var aes = new AesGcm(key))
            {
                aes.Encrypt(nonce, plaintext, ciphertext, tag);
            }

            // Layout: [nonce][tag][ciphertext]
            var result = new byte[NonceSize + TagSize + ciphertext.Length];
            Buffer.BlockCopy(nonce, 0, result, 0, NonceSize);
            Buffer.BlockCopy(tag, 0, result, NonceSize, TagSize);
            Buffer.BlockCopy(ciphertext, 0, result, NonceSize + TagSize, ciphertext.Length);
            return result;
        }

        public byte[] Decrypt(byte[] ciphertext, byte[] key)
        {
            if (ciphertext == null) throw new ArgumentNullException(nameof(ciphertext));
            if (key == null) throw new ArgumentNullException(nameof(key));

            // Validate minimum length: nonce + tag must be present.
            if (ciphertext.Length < NonceSize + TagSize)
                throw new ArgumentException("Ciphertext is too short to be valid.", nameof(ciphertext));

            var nonce = new byte[NonceSize];
            var tag = new byte[TagSize];
            var actualCipherLength = ciphertext.Length - NonceSize - TagSize;
            var cipher = new byte[actualCipherLength];

            Buffer.BlockCopy(ciphertext, 0, nonce, 0, NonceSize);
            Buffer.BlockCopy(ciphertext, NonceSize, tag, 0, TagSize);
            Buffer.BlockCopy(ciphertext, NonceSize + TagSize, cipher, 0, actualCipherLength);

            var plaintext = new byte[actualCipherLength];
            using (var aes = new AesGcm(key))
            {
                // Throws CryptographicException if authentication tag is invalid.
                aes.Decrypt(nonce, cipher, tag, plaintext);
            }
            return plaintext;
        }
    }

    public sealed class EntropyPool
    {
        private static readonly Lazy<EntropyPool> _instance =
            new Lazy<EntropyPool>(() => new EntropyPool(), LazyThreadSafetyMode.ExecutionAndPublication);
        public static EntropyPool Instance => _instance.Value;

        private readonly byte[] _pool;
        private int _position;
        private readonly object _lock = new object();
        private readonly int _poolSize;

        private EntropyPool()
        {
            _poolSize = 4096;
            _pool = new byte[_poolSize];
            ReseedPool();
            _position = 0;
        }

        private void ReseedPool()
        {
            using var rng = RandomNumberGenerator.Create();
            rng.GetBytes(_pool);
        }

        public byte[] GetEntropy(int count)
        {
            var result = new byte[count];
            lock (_lock)
            {
                if (_position + count > _poolSize)
                {
                    // Pool exhausted - reseed from OS CSPRNG
                    ReseedPool();
                    _position = 0;
                }
                Buffer.BlockCopy(_pool, _position, result, 0, count);
                _position += count;
            }
            return result;
        }
    }

    public class SecureTokenService : ITokenService
    {
        private readonly IEncryptionService _encryption;
        private readonly byte[] _masterKey;
        private readonly ConcurrentDictionary<string, DateTime> _activeTokens;

        public SecureTokenService(IEncryptionService encryption)
        {
            _encryption = encryption;
            _masterKey = new byte[32];
            using var rng = RandomNumberGenerator.Create();
            rng.GetBytes(_masterKey);
            _activeTokens = new ConcurrentDictionary<string, DateTime>();
        }

        public string GenerateSessionToken(string userId)
        {
            var entropy = EntropyPool.Instance.GetEntropy(32);
            var timestamp = BitConverter.GetBytes(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            var userBytes = Encoding.UTF8.GetBytes(userId);

            var tokenData = new byte[entropy.Length + timestamp.Length + userBytes.Length];
            Buffer.BlockCopy(entropy, 0, tokenData, 0, entropy.Length);
            Buffer.BlockCopy(timestamp, 0, tokenData, entropy.Length, timestamp.Length);
            Buffer.BlockCopy(userBytes, 0, tokenData, entropy.Length + timestamp.Length, userBytes.Length);

            var encrypted = _encryption.Encrypt(tokenData, _masterKey);
            var token = Convert.ToBase64String(encrypted);

            _activeTokens[token] = DateTime.UtcNow.AddHours(24);
            return token;
        }

        public bool ValidateToken(string token)
        {
            if (!_activeTokens.TryGetValue(token, out var expiry))
                return false;
            if (DateTime.UtcNow > expiry)
            {
                _activeTokens.TryRemove(token, out _);
                return false;
            }
            return true;
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class AuthController : ControllerBase
    {
        private readonly ITokenService _tokenService;

        public AuthController(ITokenService tokenService)
        {
            _tokenService = tokenService;
        }

        [HttpPost("login")]
        public IActionResult Login([FromBody] LoginRequest request)
        {
            if (string.IsNullOrEmpty(request?.Username) || string.IsNullOrEmpty(request?.Password))
                return BadRequest("Invalid credentials");

            // Authentication logic would go here
            if (!AuthenticateUser(request.Username, request.Password))
                return Unauthorized();

            var token = _tokenService.GenerateSessionToken(request.Username);
            return Ok(new { sessionToken = token });
        }

        [HttpPost("validate")]
        public IActionResult Validate([FromBody] TokenValidationRequest request)
        {
            if (string.IsNullOrEmpty(request?.Token))
                return BadRequest();

            return _tokenService.ValidateToken(request.Token) ? Ok() : Unauthorized();
        }

        private bool AuthenticateUser(string username, string password)
        {
            // Placeholder - would use bcrypt/argon2 in production
            return !string.IsNullOrEmpty(username) && !string.IsNullOrEmpty(password);
        }
    }

